using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00001 : ControllerTestBase
    {
        [TestMethod]
        public void Never_Use_Allow_Anonymous_On_Controllers()
        {
            var returnAwaitOnly = (from controller in Controllers
                                   from attribute in controller.Attributes
                                   where attribute.Name.Contains("AllowAnonymous")
                                   select new
                                   {
                                       ErrorClass = controller.FullQualifiedName,
                                       Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:       {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: 

{controller.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

{controller.SyntaxTree.Replace("[AllowAnonymous]", string.Empty).FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                   }).ToImmutableList();

            Assert.IsTrue(returnAwaitOnly.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00001

Please never use [AllowAnonymous] attributes on controllers. Findings {returnAwaitOnly.Count}': {Environment.NewLine}{returnAwaitOnly.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }


}
